<?php require_once 'config/config.php'; require_room();$rid=room_id();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(room_role()!=='manager')exit('Manager access required.');$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');if($title===''||$body==='')$error='Title and message are required.';else{db()->prepare("INSERT INTO notices(room_id,title,body,created_by) VALUES(?,?,?,?)")->execute([$rid,$title,$body,user()['id']]);flash('Notice published.');redirect('notices.php');}}$q=db()->prepare("SELECT n.*,u.name FROM notices n JOIN users u ON u.id=n.created_by WHERE n.room_id=? ORDER BY n.created_at DESC");$q->execute([$rid]);$rows=$q->fetchAll();$title='Notices';include 'includes/header.php';?><div class="d-flex justify-content-between mb-4"><div><h2 class="fw-bold">Notices</h2><p class="small-muted">Important updates for the whole room.</p></div></div><?php if(room_role()==='manager'):?><div class="card p-4 mb-4"><h5 class="fw-bold">Publish notice</h5><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input class="form-control mb-2" name="title" placeholder="Notice title" required><textarea class="form-control mb-2" rows="3" name="body" placeholder="Write your notice..." required></textarea><button class="btn btn-dark">Publish</button></form></div><?php endif;?><div class="d-grid gap-3"><?php foreach($rows as $n):?><div class="card p-4 notice"><h5 class="fw-bold"><?=e($n['title'])?></h5><p class="mb-2"><?=nl2br(e($n['body']))?></p><div class="small-muted"><?=e($n['name'])?> · <?=e($n['created_at'])?></div></div><?php endforeach; if(!$rows):?><div class="card p-4 text-center small-muted">No notices yet.</div><?php endif;?></div><?php include 'includes/footer.php';?>